import { lesson as L, main, exercise } from './lesson-data.js';

export const bridges = [
  L('ownership', 'strings', 'Own a piece of editable text', {
    objective: 'Create a String and append text to it.', prerequisites: ['arrays', 'parameters'], introduces: ['String', 'constructor', 'associated-path', 'method-call', 'owned-text'],
    explain: ['The quoted text you have printed is written directly into the program. A String is a value that owns editable text. Owning means it is responsible for keeping that text available and releasing its storage when it is no longer needed.', 'String::from("Ada") creates an owned String containing Ada. The :: selects a function associated with the String type; from is its constructor here. This differs from a dot, which calls a method on an existing value.', 'name.push_str("!") calls the push_str method on name and appends text. Because the contents change, name must be declared mut. .len() reports how many bytes the text occupies; for the plain A–Z letters here, one letter occupies one byte.'],
    ...exercise('fn greeting() -> String', '    let mut name = String::from("Ada");\n    name.push_str("!");\n    name', 'fn main() {\n    assert_eq!(greeting(), "Ada!");\n    println!("{}", greeting());\n}'), expected: 'Ada!',
    practiceInstruction: 'Create an owned String for Ada, append ! with push_str, and return it.', walkthrough: ['String::from creates the editable text.', 'The method appends an exclamation mark; the final expression returns the String.'], pitfall: 'A text literal and an owned String are different types. String::from is the explicit conversion used here.',
    question: 'What does push_str do?', choices: ['Appends text to this String', 'Prints the String', 'Creates a number'], answer: 0, feedback: 'push_str changes the String contents; println! displays them.', experiment: 'Append a second short piece of text and update the expected assertion.', hints: ['Use let mut name = String::from("Ada");.', 'Append with name.push_str("!");, then return name without a semicolon.']
  }),
  L('ownership', 'formatting', 'Build formatted text as a value', {
    objective: 'Use format! to create a String without printing it.', prerequisites: ['strings'], introduces: ['format-string', 'format-macro', 'macro'],
    explain: ['println! displays a message. format! uses the same placeholders but returns an owned String instead of displaying anything. That lets another function use the finished text.', 'The ! on these names marks a macro, a supplied operation that expands into Rust code before compilation. You can use these standard macros without writing a macro definition.', 'Named placeholders such as {score} use the binding of that name. An empty {} uses the value following the comma, such as format!("score {}", score). Use one supplied value for each empty placeholder.'],
    ...exercise('fn score_label(score: u32) -> String', '    format!("score {score}")', 'fn main() {\n    let label = score_label(90);\n    assert_eq!(label, "score 90");\n    println!("{label}");\n}'), expected: 'score 90',
    practiceInstruction: 'Return a formatted String containing score followed by the supplied number.', walkthrough: ['format! creates the String score 90.', 'Only the later println! displays it.'], pitfall: 'Returning println!(...) returns unit (), because printing does not produce a String.',
    question: 'Which command returns an owned String?', choices: ['format!', 'println!', 'assert!'], answer: 0, feedback: 'format! builds text for the caller; it does not send it to output.', experiment: 'Build a label with two values and two placeholders.', hints: ['Use format! rather than println! inside the helper.', 'format!("score {score}") is the returned expression.']
  }),
  L('ownership', 'scope', 'Notice where a name is usable', {
    objective: 'Identify the block that owns a local value.', prerequisites: ['clone'], introduces: ['scope', 'drop', 'shadowing'],
    explain: ['A scope is the region where a name can be used. A binding declared inside a block normally remains usable until that block’s closing brace.', 'When an owned value’s scope ends, Rust drops it: it releases the resources the value owns. You do not manually free a String.', 'An inner block can declare a new binding with the same spelling as an outer one. This is shadowing: the inner name temporarily hides the outer name, but it does not change the outer value.'],
    body: '    let name = String::from("outer");\n    {\n        let name = String::from("inner");\n        println!("{name}");\n    }\n    println!("{name}");', starter: main('    let name = String::from("outer");\n    {\n        let name = String::from("replace me");\n        println!("{name}");\n    }\n    println!("{name}");'), expected: 'inner\nouter',
    practiceInstruction: 'Change only the inner String to inner. Keep the two scopes and the outer value.', walkthrough: ['Inside the nested braces, name refers to the inner String.', 'After the inner block closes, that String is dropped and the outer name is visible again.'], pitfall: 'A name declared only inside the inner block cannot be used after the closing brace.',
    question: 'Does the inner binding change the outer String?', choices: ['No', 'Yes', 'Only when printed'], answer: 0, feedback: 'These are two different bindings; the inner one shadows the outer one temporarily.', experiment: 'Rename the inner binding to a different name and predict which names are usable after the block.', hints: ['Find the String::from call inside the nested braces.', 'Replace replace me with inner; leave outer unchanged.']
  }),
  L('borrowing', 'references', 'Read a String without taking it', {
    objective: 'Pass shared access to a function while the caller keeps ownership.', prerequisites: ['scope'], introduces: ['shared-reference', 'borrow', 'borrowed-parameter'],
    explain: ['Moving a String gives away its ownership. A reference gives temporary access instead. &name creates a shared reference to the String owned by name.', 'A parameter of type &String accepts that shared access. The receiving function can read the contents but does not own them and cannot change them through this reference.', 'After this call, name is still the owner and can be printed again. A shared borrow must not overlap a change that could invalidate what it reads. The owner must also stay alive for every use of the reference.'],
    ...exercise('fn name_length(name: &String) -> usize', '    name.len()', 'fn main() {\n    let name = String::from("Ada");\n    assert_eq!(name_length(&name), 3);\n    println!("{} {name}", name_length(&name));\n}'), expected: '3 Ada',
    practiceInstruction: 'Read the borrowed String’s byte length using len(). Do not clone or consume it.', walkthrough: ['&name lends shared access to the call.', 'The call returns a length; the caller still owns and prints name.'], pitfall: 'Removing & from the parameter and call changes this from borrowing to moving.',
    question: 'Who owns the String during the call?', choices: ['The caller’s name binding', 'The reference itself', 'Both functions independently'], answer: 0, feedback: 'The reference supplies access while the original binding keeps ownership.', experiment: 'Call name_length twice and verify that the original name remains usable.', hints: ['The parameter is already borrowed; read its contents with a method.', 'Return name.len().'], showOwnershipWalkthrough: true
  }),
  L('borrowing', 'text-slices', 'Read a view of text with &str', {
    objective: 'Use one borrowed-text parameter with a literal and an owned String.', prerequisites: ['references'], introduces: ['str', 'text-slice', 'as-str'],
    explain: ['&str is a shared reference to a view of UTF-8 text. Unlike &String, it does not require the owner to be a String: the view can also refer to text written directly in the program.', 'A String’s .as_str() method returns such a borrowed text view. It creates neither another owner nor a copy of the text.', 'The literal "Ada" can already be passed as &str. A function taking &str is therefore a useful choice when it only needs to read text.'],
    ...exercise('fn text_length(text: &str) -> usize', '    text.len()', 'fn main() {\n    let owned = String::from("Ada");\n    assert_eq!(text_length("Ada"), 3);\n    assert_eq!(text_length(owned.as_str()), 3);\n    println!("{}", text_length(owned.as_str()));\n}'), expected: '3',
    practiceInstruction: 'Return the borrowed text view’s length without allocating another String.', walkthrough: ['The literal and the String view use the same parameter type.', 'The owner stays alive while the view is used.'], pitfall: 'The &str view does not keep its owner alive by itself.',
    question: 'Does as_str() create an independent owned String?', choices: ['No', 'Yes', 'Only for long text'], answer: 0, feedback: 'It borrows a view of the existing contents.', experiment: 'Pass a different literal and an owned String with the same contents.', hints: ['Use the len method on the borrowed view.', 'Return text.len().']
  }),
  L('borrowing', 'unicode', 'Distinguish bytes from letters', {
    objective: 'Explain why UTF-8 text can occupy more bytes than visible letters.', prerequisites: ['text-slices', 'numbers'], introduces: ['byte', 'UTF-8', 'character', 'char', 'text-escapes', 'byte-iteration'],
    explain: ['A byte is a small storage unit represented by u8, a number from zero through 255. UTF-8 is the rule Rust uses to represent text as bytes. English letters such as A occupy one byte, but é occupies two.', 'text.len() counts bytes, not visible letters. café has five bytes: c, a, and f use one each, and é uses two. This distinction matters when a file reserves a fixed number of bytes for a name.', 'Double quotes describe text such as "Ada". Single quotes describe one Rust character, such as \'A\'. A character has type char. To put a quote inside a character literal, escape it as \'\\\'\'; \\n inside text represents a newline and \\0 represents a zero byte.', 'Text provides .bytes() to visit its UTF-8 bytes and .chars() to visit its characters. A for loop can visit them as it visits a numeric range. A later lesson will explain the iterator interface behind these operations.'],
    body: '    let text = "café";\n    println!("{} bytes", text.len());\n    for letter in text.chars() {\n        println!("{letter}");\n    }', starter: main('    let text = "cafe";\n    println!("{} bytes", text.len());\n    for letter in text.chars() {\n        println!("{letter}");\n    }'), expected: '5 bytes\nc\na\nf\né',
    practiceInstruction: 'Change cafe to café. Observe the byte length and the four character lines.', walkthrough: ['len reports the five bytes used by the text.', 'The loop visits four characters, including the two-byte é as one character.'], pitfall: 'A byte offset in the middle of a multi-byte character is not a valid place to slice text.',
    question: 'What does "café".len() count?', choices: ['Five UTF-8 bytes', 'Four bytes', 'Only ASCII letters'], answer: 0, feedback: 'len counts bytes, and é needs two of them.', experiment: 'Replace the text with a single crab emoji and compare its byte length with its character output.', hints: ['Use the accented final letter é in the text.', 'The text needs to be "café", not "cafe".']
  }),
  L('borrowing', 'borrowed-slices', 'Borrow part of an array', {
    objective: 'Pass a checked, known-valid array range as a borrowed slice.', prerequisites: ['arrays', 'mutable'], introduces: ['slice', 'slice-range', 'slice-iteration'],
    explain: ['A slice is a borrowed view of a sequence, with a known length. &[u32] means shared access to a sequence of u32 values; it does not fix the number of elements in the type.', '&values[1..3] borrows the elements at indices one and two. As with a numeric range, .. excludes the upper boundary. The owner must remain alive while the slice is used.', 'A for loop over a shared slice gives a shared reference to each value. *value reads the referenced integer. This is dereferencing, the same operation you used with a mutable reference.'],
    ...exercise('fn total(values: &[u32]) -> u32', '    let mut result = 0;\n    for value in values { result += *value; }\n    result', 'fn main() {\n    let values = [10, 20, 30];\n    assert_eq!(total(&values[1..3]), 50);\n    assert_eq!(total(&[]), 0);\n    println!("{}", total(&values));\n}'), expected: '60',
    practiceInstruction: 'Add each referenced integer to a mutable total, then return that total. An empty slice should return zero.', walkthrough: ['The full slice visits ten, twenty, and thirty.', 'The shorter slice visits only twenty and thirty; no owner is copied.'], pitfall: 'The range must fit the array; slicing past its end stops the program.',
    question: 'Which indices are in [1..3]?', choices: ['1 and 2', '1, 2, and 3', 'Only 3'], answer: 0, feedback: 'The start is included and the end is excluded.', experiment: 'Pass &values[0..0] and predict the total.', hints: ['Start a mutable result at zero.', 'Use result += *value inside the loop, then return result.']
  }),
  L('borrowing', 'static-text', 'Read the lifetime of a text literal', {
    objective: 'Recognise why a function can return a view of literal text.', prerequisites: ['text-slices', 'scope'], introduces: ['lifetime', 'static-reference'],
    explain: ['A lifetime is the period for which a reference is valid. References must not be used after the data they refer to is gone.', 'Literal text is part of the program itself, so a view of it can remain valid for the whole program. &\'static str states that property. Here the apostrophe introduces the lifetime name static; it is not a character literal.', 'This annotation is useful for fixed error messages later. It does not mean every reference is static, and it cannot make a reference to a local String last longer. The later lifetimes lesson covers references borrowed from function inputs.'],
    ...exercise("fn ready_message() -> &'static str", '    "Ready"', 'fn main() {\n    assert_eq!(ready_message(), "Ready");\n    println!("{}", ready_message());\n}'), expected: 'Ready',
    practiceInstruction: 'Return the literal "Ready" without making a local String or printing inside the helper.', walkthrough: ['The function returns a borrowed view of literal text.', 'That literal belongs to the program, so it outlives the call.'], pitfall: 'A local String is dropped when its scope ends; writing static cannot change that ownership rule.',
    question: 'Why is this returned text valid after the call?', choices: ['It is a literal stored with the program', 'Every local String is kept forever', 'The annotation copies all text'], answer: 0, feedback: 'The lifetime describes the existing data’s validity; it does not create or extend the data.', experiment: 'Compare this return type with -> String from the owned-text lesson.', hints: ['The returned value can be a text literal.', 'Use "Ready" as the final expression.']
  }),
  L('model', 'methods', 'Write a method for a struct', {
    objective: 'Define a method that reads a struct through &self.', prerequisites: ['structs'], introduces: ['impl', 'self', 'Self', 'method-definition'],
    explain: ['A struct groups fields. An impl block groups operations associated with that struct. impl Row { ... } says that the enclosed methods belong to Row.', 'A method’s &self parameter borrows the instance on which it is called. row.passes() supplies row automatically as self. It follows the shared-borrow rules you already know.', 'Inside the impl block, Self is another spelling for the implementing type, here Row. Lowercase self is the current instance, while uppercase Self names the type.'],
    source: 'struct Row { score: u32 }\nimpl Row {\n    fn passes(&self) -> bool { self.score >= 50 }\n}\nfn main() {\n    let row = Row { score: 50 };\n    assert!(row.passes());\n    println!("{}", row.passes());\n}\n', starter: 'struct Row { score: u32 }\nimpl Row {\n    fn passes(&self) -> bool { self.score > 50 }\n}\nfn main() {\n    let row = Row { score: 50 };\n    assert!(row.passes());\n    println!("{}", row.passes());\n}\n', expected: 'true',
    practiceInstruction: 'Fix the method’s comparison so exactly fifty passes.', walkthrough: ['The dot call borrows row as self.', 'The method reads self.score without taking ownership.'], pitfall: 'Self names a type; self names the current value. Their capitalisation matters.',
    question: 'What does &self do?', choices: ['Borrows the current instance', 'Creates a second struct', 'Imports a module'], answer: 0, feedback: 'The caller keeps ownership while the method reads the instance.', experiment: 'Create a second row with a score below fifty and test the same method.', hints: ['The method needs an inclusive comparison.', 'Use self.score >= 50.']
  }),
  L('model', 'optional-values', 'Represent a missing value', {
    objective: 'Handle both Some and None with match.', prerequisites: ['enums'], introduces: ['Option', 'Some', 'None', 'type-argument', 'optional-fallback'],
    explain: ['Option is a standard enum for a value that may be absent. Option<u32> means either Some(number), containing a u32, or None, containing no value. The angle brackets choose the type stored inside this standard container.', 'match handles those two variants just as it handled your own enum. Some(value) binds the contained number to value in that arm; None handles absence.', 'An Option also offers unwrap_or(fallback), which returns the contained value or the supplied fallback. Unlike unwrap(), unwrap_or handles None deliberately. unwrap() instead stops the program on None; use it only when presence is established, such as an assertion-controlled example.', 'When only the present case needs work, if let Some(value) = optional { ... } is a shorter conditional match. It runs its block once for Some and skips it for None. Use a full match when both cases need explicit actions.'],
    ...exercise('fn value_or_zero(value: Option<u32>) -> u32', '    match value { Some(number) => number, None => 0 }', 'fn main() {\n    assert_eq!(value_or_zero(None), 0);\n    assert_eq!(value_or_zero(Some(7)), 7);\n    println!("{}", value_or_zero(Some(7)));\n}'), expected: '7',
    practiceInstruction: 'Match both variants: return the stored number for Some, and zero for None.', walkthrough: ['Some(7) takes the first arm and returns seven.', 'None takes the fallback arm and returns zero.'], pitfall: 'None is not the number zero. Zero is an ordinary value that can itself be stored in Some(0).',
    question: 'How is a missing u32 represented?', choices: ['None', 'Some(0)', 'An uninitialised number'], answer: 0, feedback: 'None explicitly records absence; Some(0) records a present zero.', experiment: 'Compare Some(0) and None with assert_eq! or a match.', hints: ['Use a match expression with one arm per variant.', 'Some(number) => number and None => 0 handle both cases.']
  }),
  L('errors', 'result-basics', 'Separate success from failure', {
    objective: 'Return and inspect a Result with a meaningful error.', prerequisites: ['slices', 'static-text'], introduces: ['Result', 'Ok', 'Err', 'error-value', 'result-unwrapping'],
    explain: ['Option says a value may be missing. Result says an operation may succeed or fail with a reason. Result<u32, &\'static str> stores either Ok(number) or Err(message). The two type arguments specify the successful value and error types.', 'A recoverable failure is returned as data, so the caller can choose what to do. A positive-id rule can reject zero without stopping the whole program.', 'Result methods is_ok() and is_err() inspect which variant is present. unwrap() returns an Ok value but stops on Err; it is used in worked examples only for inputs whose success has been established by the shown checks.'],
    ...exercise("fn positive(id: u32) -> Result<u32, &'static str>", '    if id == 0 { Err("id must be positive") } else { Ok(id) }', 'fn main() {\n    assert_eq!(positive(0), Err("id must be positive"));\n    assert_eq!(positive(7), Ok(7));\n    println!("{}", positive(7).unwrap());\n}'), expected: '7',
    practiceInstruction: 'Return Err with the shown message for zero, and Ok(id) otherwise.', walkthrough: ['Zero produces an error value instead of a panic.', 'The successful input produces Ok(7), which the example safely unwraps.'], pitfall: 'Printing an error and returning Ok would tell the caller that the operation succeeded.',
    question: 'Which Result variant carries failure?', choices: ['Err', 'Some', 'Ok'], answer: 0, feedback: 'Err contains the error value; Ok contains the successful result.', experiment: 'Use match at the call site to print the error for zero instead of unwrapping it.', hints: ['Use the existing zero comparison to choose a Result variant.', 'Return Err("id must be positive") for zero and Ok(id) otherwise.']
  }),
  L('errors', 'checked-arithmetic', 'Turn overflow into a result', {
    objective: 'Convert a failed checked calculation into a recoverable error.', prerequisites: ['result'], introduces: ['checked-add', 'overflow', 'ok-or'],
    explain: ['A numeric type has a largest representable value. Adding beyond it is overflow. u32::MAX is the named largest u32 value; :: also selects constants associated with a type.', 'checked_add returns Some(sum) when the sum fits and None when it does not. That makes the exceptional case explicit instead of relying on how an unchecked calculation happens to run.', '.ok_or(message) converts Some(value) into Ok(value), or None into Err(message). It connects an optional calculation with an error-reporting function.'],
    ...exercise("fn safe_add(a: u32, b: u32) -> Result<u32, &'static str>", '    a.checked_add(b).ok_or("overflow")', 'fn main() {\n    assert_eq!(safe_add(19, 23), Ok(42));\n    assert_eq!(safe_add(u32::MAX, 1), Err("overflow"));\n    println!("{}", safe_add(19, 23).unwrap());\n}'), expected: '42',
    practiceInstruction: 'Use checked_add and convert its Option into Result with the error message overflow.', walkthrough: ['Nineteen plus twenty-three fits, producing Some(42).', 'ok_or turns that into Ok(42); an overflowing input instead becomes Err.'], pitfall: 'Using + and then checking the result is too late to make the arithmetic failure explicit.',
    question: 'What does checked_add return on overflow?', choices: ['None', 'Some(0)', 'Ok(0)'], answer: 0, feedback: 'None reports that no representable sum was produced.', experiment: 'Check u32::MAX plus zero and compare it with plus one.', hints: ['Start with a.checked_add(b).', 'Append .ok_or("overflow") to turn the Option into Result.']
  }),
  L('collections', 'vector-basics', 'Use a sequence that can grow', {
    objective: 'Create a Vec, append an element, and borrow its elements.', prerequisites: ['atomic-change', 'borrowed-slices'], introduces: ['Vec', 'vec-macro', 'push', 'vector-slice'],
    explain: ['An array’s length is fixed. A Vec is an owned sequence whose length can change. vec![10, 20] creates a vector containing two elements; Vec<u32> names a vector of u32 values.', 'A mutable vector can append with push(value). Its len() reports the current number of elements. As with String, the owner is responsible for the storage.', 'A shared reference to a vector can be read as a slice. This lets the same &[u32] function accept an array view or vector view without taking ownership.'],
    ...exercise('fn three_scores() -> Vec<u32>', '    let mut values = vec![10, 20];\n    values.push(30);\n    values', 'fn main() {\n    let values = three_scores();\n    assert_eq!(values, [10, 20, 30]);\n    assert_eq!(values.len(), 3);\n    println!("{values:?}");\n}'), expected: '[10, 20, 30]',
    practiceInstruction: 'Create a two-element mutable vector, append thirty, and return it.', walkthrough: ['vec! creates the initial owned sequence.', 'push grows it to three elements.'], pitfall: 'Appending can move the vector’s backing storage, so Rust will not let you keep an overlapping borrow that would become invalid.',
    question: 'Which collection can grow with push?', choices: ['Vec', 'A fixed array', 'A u32'], answer: 0, feedback: 'Vec is the growable sequence type; arrays have a fixed length.', experiment: 'Append a fourth value and read the new len().', hints: ['Start with let mut values = vec![10, 20];.', 'Call values.push(30); before returning values.']
  }),
  L('collections', 'closures', 'Write a small operation as a value', {
    objective: 'Call a closure and recognise its parameter syntax.', prerequisites: ['vector-basics', 'return-values'], introduces: ['closure', 'closure-parameter', 'capture'],
    explain: ['A closure is a small function-like value. |value: u32| value + 5 takes an input and produces an output, much like the function you wrote earlier.', 'The vertical bars delimit its parameters. Its final expression is the result. Store it with let add_five = ...; and call it with add_five(10). Rust can often infer parameter types when the calling method already specifies them.', 'A closure can also use a surrounding value; this is called capturing. Later iterator methods accept closures to choose or transform elements.'],
    body: '    let bonus = 5;\n    let add_bonus = |value: u32| value + bonus;\n    assert_eq!(add_bonus(10), 15);\n    println!("{}", add_bonus(10));', starter: main('    let bonus = 5;\n    let add_bonus = |value: u32| value;\n    assert_eq!(add_bonus(10), 15);\n    println!("{}", add_bonus(10));'), expected: '15',
    practiceInstruction: 'Make the closure add the captured bonus to its parameter.', walkthrough: ['The closure receives ten as value.', 'It reads the surrounding bonus and returns fifteen.'], pitfall: 'A closure parameter lives between | bars; a call still uses ordinary parentheses.',
    question: 'What does |value| introduce?', choices: ['A closure parameter', 'A text literal', 'A borrowed slice'], answer: 0, feedback: 'The bars delimit the closure’s input names.', experiment: 'Change the bonus and predict the returned value.', hints: ['The captured bonus is already available by name.', 'The closure body should be value + bonus.']
  }),
  L('collections', 'iterator-basics', 'Ask a sequence for its next item', {
    objective: 'Read iterator items until next returns None.', prerequisites: ['closures', 'optional-values', 'unicode'], introduces: ['iterator', 'iter', 'next', 'while-let', 'copied', 'collect', 'predicate'],
    explain: ['An iterator is a value that supplies items one at a time. .iter() borrows the elements of a collection. Its .next() returns Some(item) until there are no items left, then returns None.', 'while let Some(item) = iterator.next() repeats only while the result matches Some. It binds the item for that repetition and stops on None. This combines a while loop with the enum patterns you learned.', 'An iterator from .iter() yields references. .copied() can turn borrowed Copy values, such as &u32, into u32 values. .collect() gathers items into a collection; a type such as let values: Vec<u32> tells Rust what to build.', 'A predicate is an operation returning bool, often written as a closure. Iterator methods .any(predicate) and .all(predicate) test whether any or every item satisfies the rule. A later pipeline lesson combines filtering with a sum.'],
    ...exercise('fn sum_items(values: &[u32]) -> u32', '    let mut items = values.iter();\n    let mut total = 0;\n    while let Some(value) = items.next() { total += *value; }\n    total', 'fn main() {\n    assert_eq!(sum_items(&[]), 0);\n    assert_eq!(sum_items(&[1, 2, 3]), 6);\n    println!("{}", sum_items(&[1, 2, 3]));\n}'), expected: '6',
    practiceInstruction: 'Create an iterator, repeatedly read its next item, and add each dereferenced integer.', walkthrough: ['next yields Some(&1), Some(&2), and Some(&3).', 'The next None ends the loop and the function returns six.'], pitfall: 'The iterator must be mutable because next advances its position.',
    question: 'What signals the end of an iterator?', choices: ['None', 'Some(0)', 'A panic'], answer: 0, feedback: 'None means no next item remains; a zero can still be an ordinary item.', experiment: 'Use values.iter().copied().collect() with a Vec<u32> type annotation.', hints: ['Use let mut items = values.iter(); and a mutable total.', 'while let Some(value) = items.next() lets you add *value until the sequence ends.']
  }),
  L('collections', 'imports', 'Find names in the standard library', {
    objective: 'Read a standard-library path and introduce a short imported name.', prerequisites: ['iterators'], introduces: ['module', 'std', 'use', 'path', 'import'],
    explain: ['Rust’s standard library supplies reusable types and functions. std is its top-level name. A module groups related names, and :: steps through that grouping.', 'std::cmp::min names the min function in the cmp comparison module. use std::cmp::min; makes the short name min available in this file.', 'This is why later collection examples write use std::collections::HashMap;. Importing a name does not download a package: these examples use the standard library already provided by the browser compiler.'],
    source: 'use std::cmp::min;\n\nfn main() {\n    let smaller = min(7, 3);\n    assert_eq!(smaller, 3);\n    println!("{smaller}");\n}\n', starter: 'use std::cmp::min;\n\nfn main() {\n    let smaller = min(7, 9);\n    assert_eq!(smaller, 3);\n    println!("{smaller}");\n}\n', expected: '3',
    practiceInstruction: 'Keep the import and change the second argument so min(7, ...) returns three.', walkthrough: ['use introduces the short function name.', 'min compares the two inputs and returns the smaller value.'], pitfall: 'use changes which names are available; it is not a function call and has no parentheses.',
    question: 'What does use do here?', choices: ['Introduces a shorter name for an existing item', 'Downloads a crate', 'Executes min immediately'], answer: 0, feedback: 'The imported name is available for later calls in this file.', experiment: 'Remove the import and call std::cmp::min(7, 3) with its full path.', hints: ['The minimum of seven and three is three.', 'Use min(7, 3).']
  }),
  L('collections', 'sets', 'Record whether a value was seen', {
    objective: 'Use a HashSet to distinguish a new value from a repeated one.', prerequisites: ['maps'], introduces: ['HashSet', 'set-membership', 'unique-values'],
    explain: ['A map associates keys with values. A set records only whether each value is present. HashSet<u32> therefore stores unique integers without a separate associated value.', 'HashSet::new() creates an empty set. insert(value) returns true if it added a new member, and false if that member was already present. contains(&value) checks membership.', 'TinyDB later uses a set of visited page IDs to reject a page-link cycle: encountering a page twice can signal an invalid file. Set iteration order, like hash-map order, is unspecified.'],
    source: 'use std::collections::HashSet;\n\nfn main() {\n    let mut seen = HashSet::new();\n    assert!(seen.insert(7));\n    assert!(!seen.insert(7));\n    assert!(seen.contains(&7));\n    println!("{}", seen.len());\n}\n', starter: 'use std::collections::HashSet;\n\nfn main() {\n    let mut seen = HashSet::new();\n    assert!(seen.insert(7));\n    assert!(!seen.insert(8));\n    assert!(seen.contains(&7));\n    println!("{}", seen.len());\n}\n', expected: '1',
    practiceInstruction: 'Make the second insertion repeat seven so it reports an existing member and the set keeps one value.', walkthrough: ['The first seven is new, so insert returns true.', 'The repeated seven does not add a second member.'], pitfall: 'A set removes duplicates; it is not a counter of how many times an item was seen.',
    question: 'What does insert return for an existing member?', choices: ['false', 'true', 'Its index'], answer: 0, feedback: 'false means the set already contained that member.', experiment: 'Insert eight after the duplicate check and predict the new length.', hints: ['The duplicate must have the same value as the first insertion.', 'Change the second inserted value from eight to seven.']
  }),
  L('abstraction', 'derive', 'Ask Rust to generate a trait implementation', {
    objective: 'Use derive to inspect, compare, and clone a simple struct.', prerequisites: ['generics'], introduces: ['derive', 'attribute', 'Debug', 'PartialEq'],
    explain: ['An attribute supplies an instruction about the item below it. #[derive(Debug, PartialEq, Clone)] asks Rust to generate implementations of those traits for the following struct, when its fields support them.', 'Debug enables {:?} inspection. PartialEq enables equality comparisons, including assert_eq!. Clone enables an explicit .clone(). You have used these behaviours on standard types; now your own type can support them too.', 'This does not automatically make the type Copy. A struct containing a String still owns text and needs an explicit clone to make a separate owner.'],
    source: '#[derive(Debug, PartialEq, Clone)]\nstruct Score { value: u32 }\n\nfn main() {\n    let first = Score { value: 90 };\n    let second = first.clone();\n    assert_eq!(first, second);\n    println!("{second:?}");\n}\n', starter: '#[derive(Debug, PartialEq, Clone)]\nstruct Score { value: u32 }\n\nfn main() {\n    let first = Score { value: 80 };\n    let second = first.clone();\n    assert_eq!(first, second);\n    println!("{second:?}");\n}\n', expected: 'Score { value: 90 }',
    practiceInstruction: 'Set the stored score to ninety and keep the derived traits and clone check.', walkthrough: ['derive supplies the three implementations for Score.', 'The cloned value compares equal and can be inspected with debug formatting.'], pitfall: 'Debug formatting is an inspection aid, not a stable file format.',
    question: 'Which derived trait allows {:?} formatting?', choices: ['Debug', 'Clone', 'PartialEq'], answer: 0, feedback: 'Debug supplies the readable inspection representation.', experiment: 'Remove Debug from derive and inspect the compiler’s explanation of the formatting failure.', hints: ['The field value controls the displayed score.', 'Set value: 90 in the Score construction.']
  }),
  L('abstraction', 'aliases', 'Give a recurring type a readable name', {
    objective: 'Use a generic type alias for a repeated Result type.', prerequisites: ['derive', 'result-basics'], introduces: ['type-alias', 'generic-alias', 'pub', 'visibility'],
    explain: ['A type alias gives an existing type another name. type DbResult<T> = Result<T, String>; says that DbResult uses a String error while T still chooses the success type.', 'For example, DbResult<u32> means Result<u32, String>, and DbResult<()> means a result that reports success without another value. The alias creates no new storage or conversion.', 'pub before an item makes it public, so another module can use it. Items without pub are private to their module by default. The full TinyDB source uses public Row, Database, and Session operations with private helpers.'],
    source: 'type DbResult<T> = Result<T, String>;\n\nfn positive(value: u32) -> DbResult<u32> {\n    if value == 0 { Err(String::from("zero")) } else { Ok(value) }\n}\n\nfn main() {\n    assert!(positive(0).is_err());\n    assert_eq!(positive(7), Ok(7));\n    println!("{}", positive(7).unwrap());\n}\n', starter: 'type DbResult<T> = Result<T, String>;\n\nfn positive(value: u32) -> DbResult<u32> {\n    todo!("Return an error for zero and the value otherwise")\n}\n\nfn main() {\n    assert!(positive(0).is_err());\n    assert_eq!(positive(7), Ok(7));\n    println!("{}", positive(7).unwrap());\n}\n', expected: '7',
    practiceInstruction: 'Implement positive using the alias: return a String error for zero and Ok(value) otherwise.', walkthrough: ['The alias fixes the error type to String.', 'The success type remains u32 for this function.'], pitfall: 'An alias is another spelling of a type; it does not validate a value automatically.',
    question: 'What does DbResult<u32> stand for here?', choices: ['Result<u32, String>', 'Option<u32>', 'A separate numeric type'], answer: 0, feedback: 'The alias substitutes u32 for T and retains the String error type.', experiment: 'Write a second function returning DbResult<()> and return Ok(()) on success.', hints: ['The zero case needs Err(String::from("zero")).', 'The other case returns Ok(value).']
  }),
  L('bytes', 'files', 'Write and reopen bytes', {
    objective: 'Save a byte sequence and read the same bytes back from a file.', prerequisites: ['tests', 'aliases', 'imports'], introduces: ['file', 'filesystem', 'std-fs', 'io-result', 'file-bytes'],
    explain: ['A file is a named sequence of bytes. A filesystem keeps track of those names and contents. A database file is still bytes; a file format gives those bytes a meaning.', 'std::fs::write(name, bytes) writes the supplied bytes. std::fs::read(name) returns them as Vec<u8>. Both operations return Result because file access can fail.', 'Here main returns std::io::Result<()>, a standard type alias for a result with an input/output error. ? propagates a file failure, and Ok(()) reports successful completion. This is the same Result pattern you already learned, with the library’s error type.', 'Ordinary lesson runs have a temporary filesystem: the file exists only for this run. The TinyDB workspace later saves complete file snapshots between runs. Do not infer that any editor write is automatically saved on your phone.'],
    source: 'use std::fs;\n\nfn main() -> std::io::Result<()> {\n    let bytes: [u8; 3] = [65, 66, 67];\n    fs::write("sample.bin", bytes)?;\n    let reopened = fs::read("sample.bin")?;\n    assert_eq!(reopened, bytes);\n    println!("{} bytes reopened", reopened.len());\n    Ok(())\n}\n', starter: 'use std::fs;\n\nfn main() -> std::io::Result<()> {\n    let bytes: [u8; 3] = [65, 66, 67];\n    fs::write("sample.bin", bytes)?;\n    let reopened = fs::read("missing.bin")?;\n    assert_eq!(reopened, bytes);\n    println!("{} bytes reopened", reopened.len());\n    Ok(())\n}\n', expected: '3 bytes reopened',
    practiceInstruction: 'Read back the same filename that was written. Keep the byte equality check.', walkthrough: ['The three bytes are written under sample.bin.', 'Reading that filename returns the same ordered byte sequence.'], pitfall: 'A matching filename is not proof of a valid format; a decoder must still validate the contents.',
    question: 'What does fs::read return on success?', choices: ['A vector of bytes', 'An already validated database', 'A Rust function'], answer: 0, feedback: 'The caller receives bytes and decides how to interpret them.', experiment: 'Change one byte and predict the reopened contents without changing the filename.', hints: ['Compare the quoted filename in write with the one in read.', 'Read sample.bin rather than missing.bin.']
  }),
  L('bytes', 'option-propagation', 'Stop a missing calculation with ?', {
    objective: 'Propagate None from a checked calculation in an Option-returning function.', prerequisites: ['files', 'checked-arithmetic', 'question-mark'], introduces: ['option-question-mark', 'checked-mul', 'checked-sub'],
    explain: ['You used ? with Result to return early on Err. In a function returning Option, ? returns early on None and extracts the value from Some.', 'checked_mul and checked_sub are the multiplication and subtraction counterparts of checked_add. Each returns None if the operation cannot produce a value of the chosen type.', 'This lets page-address calculations reject overflow before using an invalid offset. The return type determines which failure form ? propagates; it does not turn Option into Result by itself.'],
    ...exercise('fn byte_count(records: usize, size: usize) -> Option<usize>', '    let count = records.checked_mul(size)?;\n    Some(count)', 'fn main() {\n    assert_eq!(byte_count(3, 40), Some(120));\n    assert_eq!(byte_count(usize::MAX, 40), None);\n    println!("{}", byte_count(3, 40).unwrap());\n}'), expected: '120',
    practiceInstruction: 'Use checked_mul with ? and wrap the successful count in Some.', walkthrough: ['Three times forty produces Some(120), which ? extracts.', 'Overflow produces None, which leaves the function immediately.'], pitfall: 'A function returning Result cannot directly propagate None with ? without a deliberate conversion such as ok_or.',
    question: 'What does ? do with None here?', choices: ['Returns None immediately', 'Substitutes zero', 'Returns Err automatically'], answer: 0, feedback: 'The enclosing function returns Option, so missing results propagate as None.', experiment: 'Try zero records and predict whether the result is Some(0) or None.', hints: ['Start with records.checked_mul(size)?.', 'Return Some(count) after a successful calculation.']
  }),
  L('bytes', 'checksums', 'Check whether bytes changed', {
    objective: 'Explain what a checksum can detect and why it is not authentication.', prerequisites: ['option-propagation'], introduces: ['checksum', 'collision', 'wrapping-add', 'numeric-conversion'],
    explain: ['A checksum is a small value calculated from file bytes. Saving it alongside the data lets a reader recalculate and compare, which can reveal an accidental change.', 'This deliberately simple demonstration adds the bytes into a u32. u32::from(*byte) converts a u8 value to a larger integer type without losing information. wrapping_add deliberately wraps at the numeric limit; it is appropriate here only because this checksum’s rule explicitly defines that behaviour.', 'Different byte sequences can share a checksum. That is a collision. This toy sum gives the same result for [1, 2] and [2, 1], so matching checksums are not proof that two files are identical.', 'TinyDB uses a different checksum algorithm, FNV-1a, plus structural validation. Neither this toy checksum nor FNV-1a authenticates a file against deliberate tampering.'],
    ...exercise('fn checksum(bytes: &[u8]) -> u32', '    let mut total: u32 = 0;\n    for byte in bytes { total = total.wrapping_add(u32::from(*byte)); }\n    total', 'fn main() {\n    assert_eq!(checksum(&[1, 2, 3]), 6);\n    assert_eq!(checksum(&[1, 2]), checksum(&[2, 1]));\n    println!("{}", checksum(&[1, 2, 3]));\n}'), expected: '6',
    practiceInstruction: 'Convert each byte to u32 and add it using the explicitly defined wrapping rule.', walkthrough: ['The checksum for one, two, and three is six.', 'The second check demonstrates a collision rather than pretending checksums are unique.'], pitfall: 'A matching checksum does not replace exact comparisons, format validation, or authentication.',
    question: 'Can different files have the same checksum?', choices: ['Yes', 'No', 'Only empty files'], answer: 0, feedback: 'A checksum maps many possible byte sequences into a smaller space, so collisions exist.', experiment: 'Change one byte in [1, 2, 3] and then swap two bytes. Compare what this toy checksum detects.', hints: ['Keep the accumulator typed as u32.', 'For each byte use total.wrapping_add(u32::from(*byte)).']
  }),
  L('database', 'database-basics', 'Meet a table, row, and column', {
    objective: 'Describe the three fields of one stored record before using SQL.', prerequisites: ['checksums', 'structs'], introduces: ['database', 'table', 'row', 'column', 'schema', 'SQL'],
    explain: ['A database stores organised records so a later operation can find or change them. TinyDB has one table named people. A table is a collection of rows; each row describes one person.', 'The columns are the named fields in every row: id, name, and score. The id identifies one person, name is text, and score is a whole number. A schema is the rule describing these columns and the values they allow.', 'You already modelled a row with a Rust struct. The program below creates one in memory. TinyDB additionally encodes rows into files, indexes IDs, and controls when changes are saved.', 'SQL is a text command language for asking a database to read or change rows. No SQL knowledge is assumed: the next lesson explains the commands. For now, .tables and .schema are TinyDB inspection commands, with one command on each line.'],
    source: 'struct Person { id: u32, name: String, score: u32 }\nfn main() {\n    let row = Person { id: 1, name: String::from("Ada"), score: 90 };\n    assert_eq!(row.id, 1);\n    println!("{} | {} | {}", row.id, row.name, row.score);\n}\n', starter: 'struct Person { id: u32, name: String, score: u32 }\nfn main() {\n    let row = Person { id: 1, name: String::from("Ada"), score: 80 };\n    assert_eq!(row.id, 1);\n    println!("{} | {} | {}", row.id, row.name, row.score);\n}\n', expected: '1 | Ada | 90',
    practiceInstruction: 'Set this row’s score to ninety. Keep its identity, name, and three-column output.', walkthrough: ['The struct holds one row with three named fields.', 'The output displays those fields in schema order.'], pitfall: 'A table is the whole collection; a row is one record within it.',
    question: 'Which is a column name in this table?', choices: ['score', 'Ada', '90'], answer: 0, feedback: 'score names a field; Ada and 90 are values stored in fields.', experiment: 'Open the lab and inspect .schema before trying any SQL.', hints: ['Find score in the struct construction.', 'Use score: 90.'],
    lab: { filename: 'lab-database-basics.rdb', script: '.tables\n.schema\n.check' }
  }),
  L('database', 'sql-crud', 'Read and change rows with SQL', {
    objective: 'Trace INSERT, SELECT, UPDATE, and DELETE on one row.', prerequisites: ['database-basics'], introduces: ['INSERT', 'SELECT', 'UPDATE', 'DELETE', 'WHERE', 'COUNT', 'SQL-string', 'autocommit-intro'],
    explain: ['INSERT INTO people VALUES (1, \'Ada\', 90); adds one row. The values follow the schema’s id, name, score order. SQL text uses single quotes; the final semicolon ends the statement.', 'SELECT * FROM people; reads all columns from all rows. WHERE id = 1 limits the operation to that ID. SELECT COUNT(*) FROM people; reports how many rows match.', 'UPDATE people SET score = 95 WHERE id = 1; changes that row’s score. DELETE FROM people WHERE id = 1; removes the row. These four kinds of operation are often called CRUD: create, read, update, delete.', 'The lab uses the real Rust database. Each standalone write saves a committed change, called autocommit. Later lessons explain transactions that group writes together. SQL runs in the TinyDB workspace; the small Rust exercise below models the same field change.', 'In the supplied Rust helper, let _ = old; explicitly ignores the previous value. The underscore pattern is the ignore pattern from the enum lesson; here it is used in a let statement. The replacement input is the value that should be returned.'],
    ...exercise('fn updated_score(old: u32, replacement: u32) -> u32', '    let _ = old;\n    replacement', 'fn main() {\n    assert_eq!(updated_score(90, 95), 95);\n    println!("{}", updated_score(90, 95));\n}'), expected: '95',
    practiceInstruction: 'Return the replacement score. let _ = old; explicitly ignores the old input without a warning; keep that provided line.', walkthrough: ['An update replaces the previous field value.', 'The lab inserts, reads, updates, and finally deletes the same row.'], pitfall: 'Without an appropriate WHERE rule, a general SQL update or delete could affect many rows; this TinyDB grammar requires an ID for these writes.',
    question: 'Which command reads rows without changing them?', choices: ['SELECT', 'DELETE', 'UPDATE'], answer: 0, feedback: 'SELECT queries the data; the other commands change it.', experiment: 'Pause the lab script before DELETE and inspect the updated row.', hints: ['The replacement is the new field value.', 'Keep let _ = old; and return replacement.'],
    lab: { filename: 'lab-sql-crud.rdb', script: "INSERT INTO people VALUES (1, 'Ada', 90);\nSELECT * FROM people;\nUPDATE people SET score = 95 WHERE id = 1;\nSELECT * FROM people WHERE id = 1;\nDELETE FROM people WHERE id = 1;\nSELECT COUNT(*) FROM people;" }
  }),
  L('pages', 'recursion', 'Repeat a smaller version of a problem', {
    objective: 'Trace a recursive function until its base case stops further calls.', prerequisites: ['page-layout', 'return-values'], introduces: ['recursion', 'base-case', 'recursive-step'],
    explain: ['A recursive function calls itself to solve a smaller version of the same problem. sum_down(3) can ask for sum_down(2), then add three to that returned result.', 'A base case ends the chain of calls. Here zero returns zero without another call. Each nonzero call subtracts one from the next input, so the small examples eventually reach that base case.', 'The results return back through the waiting calls: zero, then one, then three, then six for an input of three. The tree implementation uses the same idea by following a child until it reaches a leaf.', 'These examples use small inputs. Very deep recursion needs more call storage, so a missing base case or an unbounded depth can stop a program. TinyDB validates and bounds tree depth.'],
    ...exercise('fn sum_down(value: u32) -> u32', '    if value == 0 { 0 } else { value + sum_down(value - 1) }', 'fn main() {\n    assert_eq!(sum_down(0), 0);\n    assert_eq!(sum_down(3), 6);\n    println!("{}", sum_down(3));\n}'), expected: '6',
    practiceInstruction: 'Return zero at the base case. Otherwise add value to the recursive answer for value minus one.', walkthrough: ['Three calls two, which calls one, which calls zero.', 'The base result returns through the additions to produce six.'], pitfall: 'Calling the function again with the same input never reaches a smaller problem.',
    question: 'What stops further calls here?', choices: ['The value-zero base case', 'Printing the answer', 'The name of the function'], answer: 0, feedback: 'The zero case returns directly rather than calling the function again.', experiment: 'Trace the input four on paper before running it.', hints: ['Handle value == 0 before subtracting one.', 'Use value + sum_down(value - 1) only in the nonzero branch.']
  }),
  L('pages', 'source-primer', 'Find your way around the complete source', {
    objective: 'Locate the boundary between a TinyDB operation and its supplied helpers.', prerequisites: ['rebalance', 'aliases', 'files'], introduces: ['provided-scaffold', 'cfg', 'Path', 'PathBuf', 'read-only-helper'],
    explain: ['The complete TinyDB program is longer than a lesson example. Row validates one record. Database owns the page arena and index operations. Session chooses staged or committed state and saves files. Start from the named operation you are studying, not from the first import in the file.', 'Private helpers such as node, alloc, and branch are supplied operations. Read their input and output types, then their comments. The eight optional implementation projects remove one operation at a time while keeping the other helpers available. You are not expected to reconstruct the entire program unaided.', 'Path is a borrowed filesystem path and PathBuf is an owned path, analogous to borrowed text and an owned String. The standard Read, BufRead, and Write traits supply input/output methods. Trait imports make those methods available; these are standard-library APIs, not new SQL rules.', '#[cfg(...)] is a conditional-compilation attribute: it includes a section only for a named build target. The reference uses it for native file syncing versus the browser’s virtual filesystem. Those platform-specific helpers are provided scaffold; do not edit them for a tree or parser project.', 'All later transaction and recovery lessons still use small, complete Rust programs first. The full source and project starters are an optional extension after the relevant lessons, rather than a prerequisite for following the core course.'],
    source: 'type DbResult<T> = Result<T, String>;\n\nstruct Session { committed: u32 }\nimpl Session {\n    fn read(&self) -> DbResult<u32> { Ok(self.committed) }\n}\nfn main() {\n    let session = Session { committed: 7 };\n    assert_eq!(session.read(), Ok(7));\n    println!("{}", session.read().unwrap());\n}\n', starter: 'type DbResult<T> = Result<T, String>;\n\nstruct Session { committed: u32 }\nimpl Session {\n    fn read(&self) -> DbResult<u32> { todo!("Read the supplied field") }\n}\nfn main() {\n    let session = Session { committed: 7 };\n    assert_eq!(session.read(), Ok(7));\n    println!("{}", session.read().unwrap());\n}\n', expected: '7',
    practiceInstruction: 'Implement only read: borrow the supplied committed field and return it in Ok. Keep the alias and struct unchanged.', walkthrough: ['The struct and alias are supplied context.', 'The small method is the operation you implement, using its visible Result contract.'], pitfall: 'Treating every supplied helper as another assignment makes the project much larger than its intended learning goal.',
    question: 'What does a one-function project ask you to implement?', choices: ['The marked operation, using the supplied helpers', 'Every helper from scratch', 'The browser runtime'], answer: 0, feedback: 'The scaffold narrows the task to the named operation; use its existing contracts.', experiment: 'Download the source and locate Row, Database, and Session before reading a private helper.', hints: ['The receiver is borrowed as &self.', 'Return Ok(self.committed).']
  })
];
